// Scoped by state, not slug alone — city names repeat across states, so
// a slug-only lookup would silently resolve to the wrong city.
export function getCityBySlug(stateSlug: string, citySlug: string): City | undefined {
  return cities.find((city) => city.stateSlug === stateSlug && city.slug === citySlug);
}

export function getCitiesForState(stateSlug: string): City[] {
  return cities.filter((city) => city.stateSlug === stateSlug);
}

export function getCityBySlugAnyState(citySlug: string): City[] {
  return cities.filter((city) => city.slug === citySlug);
}
